from playwright.sync_api import sync_playwright
BOOT='''window._frames=[];window._time=0;window.requestAnimationFrame=f=>_frames.push(f);window.advance=n=>{for(let i=0;i<n;i++){_time+=1000/60;const fs=_frames.splice(0);fs.forEach(f=>f(_time));}};let seed=0;Math.random=()=>[.1,.45,.8][seed++%3];window.drive=(frames,use=true)=>{let used=[];for(let i=0;i<frames;i++){const s=kartState();if(s.mode!=='racing')break;const box=s.objects.find(o=>o.type==='box'&&o.d>s.player.d&&o.d-s.player.d<1600);const target=box?box.x:0;const diff=target-s.player.x;for(const [key,on] of [['ArrowLeft',diff<-.035],['ArrowRight',diff>.035]])window.dispatchEvent(new KeyboardEvent(on?'keydown':'keyup',{code:key,bubbles:true}));if(use&&s.heldItem){used.push(s.heldItem);window.dispatchEvent(new KeyboardEvent('keydown',{code:'Space',bubbles:true}));window.dispatchEvent(new KeyboardEvent('keyup',{code:'Space',bubbles:true}));}advance(1);}return used;}'''
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
 page=b.new_page(viewport={'width':1100,'height':900});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.add_init_script(BOOT);page.goto('http://127.0.0.1:8002/kart/');page.locator('[data-character="cat"]').click();assert page.evaluate('kartState().character')=='cat';page.locator('#action').click();page.evaluate('advance(60)');assert page.evaluate('kartState().mode')=='countdown';page.locator('#pause').click();time=page.evaluate('kartState().countdown');page.evaluate('advance(60)');assert page.evaluate('kartState().countdown')==time;page.locator('#action').click();assert page.evaluate('kartState().mode')=='countdown';page.evaluate('advance(130)');assert page.evaluate('kartState().mode')=='racing';print('PASS select racer, countdown pause and resume',flush=True)
 used=page.evaluate('drive(520)');page.screenshot(path='/tmp/kart-desktop.png');print('first stretch',used,flush=True)
 for i in range(20):
  used+=page.evaluate('drive(500)')
  if page.evaluate('kartState().mode')=='finished':break
 s=page.evaluate('kartState()');assert s['mode']=='finished',s;assert s['player']['d']==72000;assert 1<=s['finalRank']<=4;assert s['finalRank']==1+sum(r['finish'] is not None and r['finish']<=s['elapsed'] for r in s['rivals']);assert set(used)=={'candy','star','bubble'},used;assert s['best']['cat']==s['finalRank'];print('PASS 3 laps, all 3 items, rivals, final rank',s['finalRank'],flush=True)
 page.reload();assert page.evaluate('kartState().best.cat')==s['finalRank'];page.locator('#action').click();page.evaluate('advance(200)');page.keyboard.down('ArrowRight');page.evaluate('advance(200)');page.keyboard.up('ArrowRight');assert page.evaluate('kartState().player.speed')<800;page.locator('#pause').click();d=page.evaluate('kartState().player.d');page.evaluate('advance(200)');assert page.evaluate('kartState().player.d')==d;print('PASS record persistence, offroad slowing, racing pause',flush=True)
 m=b.new_page(viewport={'width':390,'height':844},is_mobile=True,has_touch=True);m.add_init_script(BOOT);m.on('pageerror',lambda e:errors.append(str(e)));m.goto('http://127.0.0.1:8002/kart/');m.locator('#action').tap();m.evaluate('advance(200)');m.evaluate('drive(200,false)');assert m.evaluate('kartState().heldItem')
 cdp=m.context.new_cdp_session(m);r=m.locator('#right').bounding_box();point={'x':r['x']+r['width']/2,'y':r['y']+r['height']/2,'id':1};cdp.send('Input.dispatchTouchEvent',{'type':'touchStart','touchPoints':[point]});before=m.evaluate('kartState().player.x');m.evaluate('advance(10)');assert m.evaluate('kartState().player.x')>before
 cdp.send('Input.dispatchTouchEvent',{'type':'touchCancel','touchPoints':[]});assert not m.evaluate('kartState().held');m.locator('#item').tap();assert m.evaluate('kartState().heldItem') is None;assert m.evaluate('kartState().boost')>0;m.evaluate('advance(5)');m.screenshot(path='/tmp/kart-mobile.png');assert m.evaluate('document.documentElement.scrollWidth<=innerWidth');assert not errors,errors
 print('PASS mobile steering, cancel, collected item tap, layout; no JS errors',flush=True);b.close()
